16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.Email;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Digits(fraction = 0, integer = 10)
51	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
62	    private Set<Pet> pets;
63	
64	    public String getAddress() {
65	        return this.address;
66	    }
67	
68	    public void setAddress(String address) {
69	        this.address = address;
70	    }
71	
72	    public String getCity() {
73	        return this.city;
74	    }
75	
76	    public void setCity(String city) {
77	        this.city = city;
78	    }
79	
80	    public String getTelephone() {
81	        return this.telephone;
82	    }
83	
84	    public void setTelephone(String telephone) {
85	        this.telephone = telephone;
86	    }
87	
88	    public String getEmail() {
89	        return this.email;
90	    }
91	
92	    /**
93	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
94	     * {@code null} value (email omitted) is preserved as {@code null}.
95	     */
96	    public void setEmail(String email) {
97	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
98	    }
99	
100	    public LocalDate getRegistrationDate() {
101	        return this.registrationDate;
102	    }
103	
104	    public void setRegistrationDate(LocalDate registrationDate) {
105	        this.registrationDate = registrationDate;
106	    }
107	
108	    protected Set<Pet> getPetsInternal() {
109	        if (this.pets == null) {
110	            this.pets = new HashSet<>();
111	        }
112	        return this.pets;
113	    }
114	
115	    protected void setPetsInternal(Set<Pet> pets) {
116	        this.pets = pets;
117	    }
118	
119	    public List<Pet> getPets() {
120	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
121	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
122	        return Collections.unmodifiableList(sortedPets);
123	    }
124	
125	    public void setPets(List<Pet> pets) {
126	        this.pets = new HashSet<>(pets);
127	    }
128	
129	    public void addPet(Pet pet) {
130	        getPetsInternal().add(pet);
131	        pet.setOwner(this);
132	    }
133	
134	    /**
135	     * Return the Pet with the given name, or null if none found for this Owner.
136	     *
137	     * @param name to test
138	     * @return true if pet name is already in use
139	     */
140	    public Pet getPet(String name) {
141	        return getPet(name, false);
142	    }
143	
144	    /**
145	     * Return the Pet with the given name, or null if none found for this Owner.
146	     *
147	     * @param name to test
148	     * @return true if pet name is already in use
149	     */
150	    public Pet getPet(String name, boolean ignoreNew) {
151	        name = name.toLowerCase();
152	        for (Pet pet : getPetsInternal()) {
153	            if (!ignoreNew || !pet.isNew()) {
154	                String compName = pet.getName();
155	                compName = compName.toLowerCase();
156	                if (compName.equals(name)) {
157	                    return pet;
158	                }
159	            }
160	        }
161	        return null;
162	    }
163	
164	    public Pet getPet(Integer petId) {
165	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
166	    }
167	
168	    @Override
169	    public String toString() {
170	        return new ToStringCreator(this)
171	
172	            .append("id", this.getId())
173	            .append("new", this.isNew())
174	            .append("lastName", this.getLastName())
175	            .append("firstName", this.getFirstName())
176	            .append("address", this.address)
177	            .append("city", this.city)
178	            .append("telephone", this.telephone)
179	            .append("email", this.email)
180	            .toString();
181	    }
182	}
