17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        List<String> missingFields = new ArrayList<>();
108	        if (isBlank(ownerFieldsDto.getFirstName())) {
109	            missingFields.add("firstName");
110	        }
111	        if (isBlank(ownerFieldsDto.getLastName())) {
112	            missingFields.add("lastName");
113	        }
114	        if (isBlank(ownerFieldsDto.getAddress())) {
115	            missingFields.add("address");
116	        }
117	        if (isBlank(ownerFieldsDto.getCity())) {
118	            missingFields.add("city");
119	        }
120	        if (isBlank(ownerFieldsDto.getTelephone())) {
121	            missingFields.add("telephone");
122	        }
123	        if (!missingFields.isEmpty()) {
124	            throw new MissingOwnerFieldsException(missingFields);
125	        }
126	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
127	        if (isTelephoneInUse(telephone)) {
128	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
129	        }
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        owner.setTelephone(telephone);
133	        if (owner.getRegistrationDate() == null) {
134	            owner.setRegistrationDate(LocalDate.now());
135	        }
136	        this.clinicService.saveOwner(owner);
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        currentOwner.setAddress(ownerFieldsDto.getAddress());
151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Transactional
161	    @Override
162	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        this.clinicService.deleteOwner(owner);
168	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        HttpHeaders headers = new HttpHeaders();
179	        Pet pet = petMapper.toPet(petFieldsDto);
180	        owner.setId(ownerId);
181	        pet.setOwner(owner);
182	        pet.getType().setName(null);
183	        this.clinicService.savePet(pet);
184	        PetDto petDto = petMapper.toPetDto(pet);
185	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
186	            .buildAndExpand(pet.getId()).toUri());
187	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner != null) {
195	            Pet currentPet = this.clinicService.findPetById(petId);
196	            if (currentPet != null) {
197	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
198	                currentPet.setName(petFieldsDto.getName());
199	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
200	                this.clinicService.savePet(currentPet);
201	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	            }
203	        }
204	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
210	        HttpHeaders headers = new HttpHeaders();
211	        Visit visit = visitMapper.toVisit(visitFieldsDto);
212	        Pet pet = new Pet();
213	        pet.setId(petId);
214	        visit.setPet(pet);
215	        this.clinicService.saveVisit(visit);
216	        VisitDto visitDto = visitMapper.toVisitDto(visit);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
218	            .buildAndExpand(visit.getId()).toUri());
219	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
220	    }
221	
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
226	        Owner owner = this.clinicService.findOwnerById(ownerId);
227	        if (owner != null) {
228	            Pet pet = owner.getPet(petId);
229	            if (pet != null) {
230	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	
236	    private static boolean isBlank(String value) {
237	        return value == null || value.isBlank();
238	    }
239	
240	    /**
241	     * Normalizes a telephone by removing every non-digit character and requiring exactly ten
242	     * digits to remain.
243	     *
244	     * @param rawTelephone the telephone value as supplied by the client
245	     * @return the stripped 10-digit telephone value
246	     * @throws InvalidTelephoneException if the stripped value is not exactly ten digits
247	     */
248	    private static String normalizeTelephone(String rawTelephone) {
249	        String digits = rawTelephone == null ? "" : rawTelephone.replaceAll("\\D", "");
250	        if (digits.length() != 10) {
251	            throw new InvalidTelephoneException(rawTelephone);
252	        }
253	        return digits;
254	    }
255	
256	    /**
257	     * Determines whether any existing owner already uses the given normalized telephone. Each
258	     * stored telephone is reduced to its digits before comparison so values that normalize to the
259	     * same number are treated as duplicates regardless of formatting.
260	     *
261	     * @param normalizedTelephone the digits-only telephone of the owner being created
262	     * @return {@code true} if another owner already has the same normalized telephone
263	     */
264	    private boolean isTelephoneInUse(String normalizedTelephone) {
265	        return this.clinicService.findAllOwners().stream()
266	            .map(Owner::getTelephone)
267	            .filter(existing -> existing != null)
268	            .map(existing -> existing.replaceAll("\\D", ""))
269	            .anyMatch(normalizedTelephone::equals);
270	    }
271	}
